INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16093, 'សិស្សស្រីពាក់ខ្សែក ផាត់ម្សៅ និងស្លៀកសំពត់ឆែក។ តើខុសប្រការណា?', NULL, '["ប្រការ ៦ សុំច្បាប់", "ប្រការ ១ ឃ ហាមតុបតែង និងសំពត់ឆែក/ខ្លី", "តារាងម៉ោងទី ១", "ប្រការ ៨ បេក្ខភាព"]', 1, NULL, 3, 'mcq', 'ហាមសំពត់ឆែក អលង្ការ ផាត់ម្សៅ។', 'បទបញ្ជាផ្ទៃក្នុង', 'pisa', 1, 'NGS', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16094, 'សិស្សមកដល់ ៧:៤០ ខណៈម៉ោងទី ១ ចាប់ ៧:៣០។ ត្រូវចាត់ទុកថា?', NULL, '["អវត្តមាន", "មិនគិតព្រោះតិចជាង ១៥ នាទី", "យឺតតែមានវត្តមាន", "មានច្បាប់ស្វ័យប្រវត្តិ"]', 0, NULL, 3, 'mcq', 'ចូលក្រោយម៉ោងកំណត់ = អវត្តមាន។', 'បទបញ្ជាផ្ទៃក្នុង', 'pisa', 1, 'NGS', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16095, 'សិស្សឈឺ មាតាបិតាសុំច្បាប់តាម APP ប៉ុន្តែខកខានប្រឡងខែ (មូលហេតុផ្ទាល់ខ្លួន)។ ពិន្ទុគឺ?', NULL, '["ពិន្ទុពេញ", "ស្មើពិន្ទុទាបជាងគេក្នុងថ្នាក់តាមមុខនោះ", "សូន្យ", "ខ្ពស់ជាងគេដក ៥"]', 1, NULL, 3, 'mcq', 'មានច្បាប់ + ផ្ទាល់ខ្លួន = ពិន្ទុទាបជាងគេ។', 'បទបញ្ជាផ្ទៃក្នុង', 'pisa', 1, 'NGS', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16096, 'សិស្សចង់ចេញមុនម៉ោងទី ៤ ព្រោះមានណាត់ពេទ្យ។ គ្រូមុខវិជ្ជាអនុញ្ញាតឱ្យទៅ។ តើត្រូវទេ?', NULL, '["ត្រូវ បើប្រធានថ្នាក់យល់ព្រម", "ត្រូវ ព្រោះគ្រូមុខវិជ្ជាអនុញ្ញាតហើយ", "មិនត្រូវ តែគណៈគ្រប់គ្រងអនុញ្ញាតបាន ហើយត្រូវមាតាបិតាសុំ", "ត្រូវ បើមិត្តនាំទៅ"]', 2, NULL, 3, 'mcq', 'គ្រូបង្រៀនមិនមានសិទ្ធិអនុញ្ញាតចេញមុនម៉ោង។', 'បទបញ្ជាផ្ទៃក្នុង', 'pisa', 1, 'NGS', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16097, 'សិស្សថ្នាក់ទី ១២ ឈប់ឥតច្បាប់ពេលប្រឡងឆមាសមុខវិជ្ជាមួយ។ លទ្ធផល?', NULL, '["គ្រាន់តែណែនាំ", "គ្មានពិន្ទុមធ្យមភាគឆមាស និងត្រូវលុបបេក្ខភាពប្រឡងសញ្ញាបត្រ", "បានខ្ពស់ជាងគេដក ៥", "បានពិន្ទុទាបជាងគេ"]', 1, NULL, 3, 'mcq', 'ប្រការ ៨ ករណីទី ២។', 'បទបញ្ជាផ្ទៃក្នុង', 'pisa', 1, 'NGS', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16098, 'សិស្សលេងហ្គេមលើទូរសព្ទក្នុងទីធ្លាសាលាគ្មានអនុញ្ញាត។ តើខុសប្រការណា?', NULL, '["តារាងម៉ោងទី ៩", "ក៧ អានសៀវភៅ", "ខ២ ហាមលេងហ្គេមលើទូរសព្ទក្នុងបរិវេណសាលា", "ប្រការ ៨ បេក្ខភាព"]', 2, NULL, 3, 'mcq', 'ខ២ នៃប្រការ ២។', 'បទបញ្ជាផ្ទៃក្នុង', 'pisa', 1, 'NGS', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
